#!/usr/bin/env python3
"""Generate the implemented foundation contract; unimplemented modules have no fake routes."""
import json
from pathlib import Path

def ref(name):return {'$ref':'#/components/schemas/'+name}
def obj(properties,required=()):return {'type':'object','additionalProperties':False,'properties':properties,'required':list(required)}
def string(**kw):return {'type':'string',**kw}
def array(item):return {'type':'array','items':item}
def response(schema,description='Success'):return {'description':description,'content':{'application/json':{'schema':schema}}}
uuid=string(format='uuid')
version={'type':'integer','minimum':1}
schemas={}
schemas['Error']=obj({'error':obj({'code':string(),'message':string(),'fields':{'type':'object','additionalProperties':{'type':'string'}}},['code','message','fields']),'request_id':uuid},['error','request_id'])
schemas['User']=obj({'id':uuid,'email':string(format='email'),'display_name':string(),'role':string(),'active':{'type':'boolean'},'version':version,'facility_ids':array(uuid)},['id','email','display_name','role','active','version','facility_ids'])
schemas['Actor']={'allOf':[ref('User'),{'type':'object','properties':{'permissions':array(string())},'required':['permissions']}]}
schemas['Tokens']=obj({'access_token':string(description='Opaque bearer credential, held in browser memory; server checks session on every request.'),'token_type':{'type':'string','enum':['Bearer']},'expires_in':{'type':'integer','example':900},'user':ref('User')},['access_token','token_type','expires_in','user'])
schemas['MobileTokens']={'allOf':[ref('Tokens'),{'type':'object','properties':{'refresh_token':string(description='Store in mobile secure credential storage. Rotation invalidates the preceding token.')},'required':['refresh_token']}]}
roles=['administrator','reception','nurse','doctor','laboratory','pharmacy','cashier','management','privacy-reviewer']
schemas['CreateStaff']=obj({'email':string(format='email',maxLength=254),'display_name':string(minLength=1,maxLength=160),'password':string(minLength=12,maxLength=256,writeOnly=True),'role':string(enum=roles),'facility_ids':{'type':'array','items':uuid,'minItems':1,'maxItems':30,'uniqueItems':True}},['email','display_name','password','role','facility_ids'])
schemas['UpdateStaff']=obj({'display_name':string(minLength=1,maxLength=160),'role':string(enum=roles),'active':{'type':'boolean'},'facility_ids':{'type':'array','items':uuid,'minItems':1,'maxItems':30,'uniqueItems':True},'version':version},['display_name','role','active','facility_ids','version'])
schemas['Facility']=obj({'id':uuid,'name':string(),'timezone':string(),'active':{'type':'boolean'}},['id','name','timezone','active'])
schemas['CreateFacility']=obj({'name':string(minLength=1,maxLength=160),'timezone':string(maxLength=100,example='Africa/Dar_es_Salaam')},['name','timezone'])
demographics={'given_name':string(minLength=1,maxLength=100),'family_name':string(minLength=1,maxLength=100),'birth_precision':string(enum=['exact','year','unknown'],description='exact requires only birth_date; year requires only birth_year; unknown omits both.'),'birth_date':string(format='date',nullable=True),'birth_year':{'type':'integer','minimum':1850,'maximum':9999,'nullable':True},'phone':string(maxLength=40,description='Shared phone numbers are allowed.'),'address':string(maxLength=500)}
required=['given_name','family_name','birth_precision']
schemas['CreatePatient']=obj({'facility_id':uuid,**demographics},['facility_id',*required])
schemas['UpdatePatient']=obj({**demographics,'version':version},[*required,'version'])
schemas['Patient']=obj({'id':uuid,'mrn':string(example='SP-0000000001'),'facility_id':uuid,**demographics,'version':version,'created_at':string(format='date-time'),'updated_at':string(format='date-time')},['id','mrn','facility_id',*required,'birth_date','birth_year','phone','address','version','created_at','updated_at'])
schemas['Login']=obj({'email':string(format='email',maxLength=254),'password':string(maxLength=256,writeOnly=True),'client_type':string(enum=['web','mobile'])},['email','password','client_type'])
schemas['Refresh']=obj({'client_type':string(enum=['web','mobile']),'refresh_token':string(maxLength=128,description='Mobile only; web must omit this and send the HttpOnly refresh cookie.')},['client_type'])
schemas['Session']=obj({'id':uuid,'client_type':string(enum=['web','mobile']),'created_at':string(format='date-time'),'expires_at':string(format='date-time'),'revoked_at':string(format='date-time',nullable=True)},['id','client_type','created_at','expires_at','revoked_at'])
schemas['AuditEvent']=obj({'id':{'type':'integer','format':'int64'},'actor_id':string(format='uuid',nullable=True),'action':string(),'resource_id':string(format='uuid',nullable=True),'patient_id':string(format='uuid',nullable=True),'request_id':uuid,'reason':string(nullable=True),'facility_id':string(format='uuid',nullable=True),'outcome':string(enum=['success','denied','failure']),'created_at':string(format='date-time')},['id','actor_id','action','resource_id','patient_id','request_id','outcome','created_at','reason','facility_id'])
schemas['Health']=obj({'status':string(enum=['ok','ready'])},['status'])
schemas['Actor']=obj({**schemas['User']['properties'],'permissions':array(string()),'mfa_verified':{'type':'boolean','description':'True only for sessions created after a verified second factor.'}},[*schemas['User']['required'],'permissions','mfa_verified'])
schemas['Challenge']=obj({'mfa_required':{'type':'boolean','enum':[True]},'challenge_token':string(description='Single-use, 5-minute, at most 5 attempts. No session exists until verified.'),'expires_in':{'type':'integer','example':300}},['mfa_required','challenge_token','expires_in'])
schemas['MFAVerify']=obj({'challenge_token':string(minLength=32,maxLength=128),'code':string(pattern='^[0-9]{6}$',description='Current TOTP code. Exactly one of code or recovery_code.'),'recovery_code':string(maxLength=32,description='Single-use recovery code, e.g. ABCD-EFGH-IJKL-MNOP.'),'client_type':string(enum=['web','mobile'])},['challenge_token','client_type'])
schemas['Enrollment']=obj({'secret':string(description='Base32 TOTP secret; show once for manual entry.'),'provisioning_uri':string(description='otpauth:// URI to render as a QR code. Never log it.')},['secret','provisioning_uri'])
schemas['MobileTokens']=obj({**schemas['Tokens']['properties'],'refresh_token':string()},[*schemas['Tokens']['required'],'refresh_token'])
paths={}
errors={str(c):response(ref('Error'),desc) for c,desc in [(400,'Malformed JSON, unknown field, or invalid body'),(401,'Missing, expired, revoked, or invalid credentials'),(403,'Permission, facility, browser-origin, or mfa_required (privileged role without MFA-verified session) denied'),(404,'Record not found in permitted scope'),(409,'Version, uniqueness, or idempotency conflict'),(413,'Body exceeds 64 KiB'),(415,'application/json required'),(422,'Validation or invalid database reference'),(426,'HTTPS required in production; forwarded schemes require a trusted proxy'),(429,'Authentication rate limit; retry after 15 minutes'),(500,'Redacted internal error'),(503,'Database not ready, or mfa_unavailable (encryption keys not configured)')]}
page=[{'name':'cursor','in':'query','schema':uuid,'description':'Exclusive last returned UUID; stable ascending UUID order.'},{'name':'limit','in':'query','schema':{'type':'integer','minimum':1,'maximum':100,'default':25}}]
def listing(name,cursor=False):return obj({'items':array(ref(name)),**({'next_cursor':string(description='Empty when exhausted; an exact full final page may require one empty follow-up request.')} if cursor else {})},['items',*(['next_cursor'] if cursor else [])])
def op(method,path,summary,schema=None,input=None,permission=None,status=200,public=False,parameters=None,description=''):
 d={'operationId':summary.replace(' ','_').lower(),'summary':summary,'description':description,'tags':[('operations' if path.startswith('/health') else 'authentication' if '/auth/' in path else 'patients' if '/patients' in path else 'administration')],'responses':{str(status):response(schema) if schema else {'description':'Completed; no content'},**errors},'security':[] if public else [{'bearerAuth':[]}]}
 if input:d['requestBody']={'required':True,'content':{'application/json':{'schema':ref(input) if isinstance(input,str) else input}}}
 if permission:d['x-permission']=permission
 params=list(parameters or [])
 if '{id}' in path:params.append({'name':'id','in':'path','required':True,'schema':uuid})
 if params:d['parameters']=params
 paths.setdefault(path,{})[method]=d
 return d
op('get','/health/live','Liveness',ref('Health'),public=True)
op('get','/health/ready','Readiness',ref('Health'),public=True,description='Checks database connectivity and exact migration version. Startup also requires a restricted database role.')
op('get','/api/openapi.json','Download OpenAPI contract',{'type':'object'},public=True)
token_response={'oneOf':[ref('Tokens'),ref('MobileTokens')]}
login=op('post','/api/v1/auth/login','Staff login',{'oneOf':[ref('Tokens'),ref('MobileTokens'),ref('Challenge')]},'Login',public=True,description='Staff with a confirmed second factor receive a Challenge (no tokens, no cookie) and must call /api/v1/auth/mfa/verify. Web requires an allowed Origin and sets a path-scoped HttpOnly SameSite=Strict cookie (Secure outside development/test). Mobile requests must have no Origin. Credentials are rate limited by direct peer IP and normalized email: 10 attempts per 15 minutes. No forwarded client IP is trusted. Access lifetime 15 minutes; session hard expiry 7 days.')
login['responses']['200']['headers']={'Set-Cookie':{'schema':string(),'description':'Web flow only: spartial_refresh; HttpOnly; SameSite=Strict; Path=/api/v1/auth; Secure in production.'}}
op('post','/api/v1/auth/refresh','Rotate refresh credential',token_response,'Refresh',public=True,description='Web uses cookie and exact allowed Origin; mobile sends refresh_token without Origin. Old access token is invalid immediately. Reusing a spent refresh token revokes its entire session, including the latest credentials. Clients must serialize refresh requests, with no automatic retry after ambiguous responses.')
op('get','/api/v1/auth/me','Current staff profile',ref('Actor'))
op('post','/api/v1/auth/logout','Revoke current session',status=204,description='Web sessions additionally require configured Origin. Clears browser cookie. Subsequent access and refresh are denied.')
op('get','/api/v1/auth/sessions','List own sessions',listing('Session'),description='Newest 100 sessions; includes revoked entries. No tokens or credential hashes are returned.')
op('post','/api/v1/auth/sessions/{id}/revoke','Revoke own session',status=204,description='Can revoke only sessions belonging to the current staff account; inaccessible IDs return 404.')
op('post','/api/v1/auth/password','Change own password',input=obj({'current_password':string(maxLength=256,writeOnly=True),'new_password':string(minLength=12,maxLength=256,writeOnly=True)},['current_password','new_password']),status=204,description='Requires current password. Revokes every session including the caller; sign in again.')
op('post','/api/v1/auth/mfa/verify','Complete second-factor login',token_response,'MFAVerify',public=True,description='Same Origin/client rules as login. Accepts a TOTP code (each 30-second step usable once, one step of drift) or an unused recovery code. Wrong, reused, expired, exhausted or stale challenges (password/role/suspension changed) return 401 and are audited. Rate limited per IP and per account. Issues an MFA-verified session.')
op('post','/api/v1/auth/mfa/enroll','Start authenticator enrollment',ref('Enrollment'),obj({'current_password':string(maxLength=256,writeOnly=True)},['current_password']),description='Pending enrollment expires after ten minutes. Management commands share a ten-attempt per-account 15-minute limit and audit denied factors/reauthentication. Requires password re-authentication. Secret is stored AES-256-GCM encrypted with a configured key bound to the staff id. 409 if a factor is already confirmed; 503 when no encryption keys are configured.')
op('post','/api/v1/auth/mfa/confirm','Confirm authenticator enrollment',obj({'recovery_codes':array(string())},['recovery_codes']),obj({'code':string(pattern='^[0-9]{6}$')},['code']),description='Returns 10 single-use recovery codes exactly once (only digests are stored). Pending enrollment must be unexpired. Upgrades the current session to MFA-verified, revokes all other sessions and invalidates pending login challenges.')
op('post','/api/v1/auth/mfa/disable','Disable second factor',input=obj({'current_password':string(maxLength=256,writeOnly=True),'code':string(pattern='^[0-9]{6}$'),'recovery_code':string(maxLength=32)},['current_password']),status=204,description='Requires password and exactly one current factor. Deletes the secret and recovery codes, invalidates pending challenges and revokes every session. Privileged roles are then blocked again where MFA is enforced.')
op('post','/api/v1/auth/mfa/recovery-codes/regenerate','Regenerate MFA recovery codes',obj({'recovery_codes':array(string())},['recovery_codes']),input=obj({'current_password':string(maxLength=256,writeOnly=True),'code':string(minLength=6,maxLength=6),'recovery_code':string(maxLength=32)},['current_password']),description='Requires password and exactly one unused current TOTP or recovery code. Replaces all ten recovery codes, shows them once, revokes other sessions and invalidates pending login challenges. Management attempts share a ten-attempt per-account 15-minute limit; failures are audited. Serialize requests and never automatically retry after an ambiguous response.')

op('get','/api/v1/staff/facilities','List facilities',listing('Facility'),permission='facilities.read',description='Assigned active facilities for ordinary staff; facility administrators can list all. Maximum 100 records in this foundation version.')
op('post','/api/v1/staff/facilities','Create facility',ref('Facility'),'CreateFacility','facilities.manage',201)
op('get','/api/v1/staff/users','List staff',listing('User',True),permission='staff.read',parameters=page)
op('post','/api/v1/staff/users','Create staff account',ref('User'),'CreateStaff','staff.manage',201,description='Administrator-only. Requires active facility references. Direct development account provisioning; invitation/activation remains pending.')
op('put','/api/v1/staff/users/{id}','Update staff account',ref('User'),'UpdateStaff','staff.manage',description='Administrator-only. Replaces account administration fields using expected version. Role, assignment, reactivation, suspension, and display-name changes revoke all target sessions. The last active administrator cannot be disabled or demoted. Email and historical authors are preserved.')
op('post','/api/v1/staff/patients','Register patient',ref('Patient'),'CreatePatient','patients.write',201,parameters=[{'name':'Idempotency-Key','in':'header','required':True,'schema':string(minLength=8,maxLength=128)}],description='Requires an assigned active facility. Durable key scoped by actor and patients.create; canonical normalized request hash; changed request returns 409. Replays the committed 201 payload. MRN, audit, outbox, and idempotency response commit in one transaction. Shared phone numbers accepted. Different keys intentionally create distinct registry entries; duplicate suggestions/merge remain pending.')
op('get','/api/v1/staff/patients','Search patients',listing('Patient',True),permission='patients.read',parameters=page+[{'name':'q','in':'query','schema':string(maxLength=100),'description':'Literal case-insensitive substring of MRN, given/family name, or phone; SQL wildcard characters are escaped.'}],description='Demographics only, limited to assigned active facilities. Reads are audited. No clinical record access is implemented.')
op('get','/api/v1/staff/patients/{id}','Read patient profile',ref('Patient'),permission='patients.read',description='Missing and cross-facility records both return 404. Authorized reads commit an audit record before response.')
op('put','/api/v1/staff/patients/{id}','Update patient profile',ref('Patient'),'UpdatePatient','patients.write',description='Full demographic replacement with expected version. Immutable facility_id and MRN; unknown fields rejected. Stale version returns 409; cross-facility returns 404. Preserves audit history.')
op('get','/api/v1/staff/audit','Read audit events',listing('AuditEvent'),permission='audit.read',parameters=[{'name':'before','in':'query','schema':{'type':'integer','format':'int64','minimum':1},'description':'Exclusive event ID; returns newest 100. Use last item ID for the next page.'}],description='Organization-wide privileged metadata review for administrator/privacy-reviewer. Contains identifiers and outcomes, no clinical notes or request bodies. Audit querying itself is recorded.')
# Care policy, independent approvals and encrypted identifiers.
schemas['AssignmentInput']=obj({'staff_id':uuid,'reason':string(minLength=20,maxLength=1000),'valid_until':string(format='date-time')},['staff_id','reason','valid_until'])
schemas['Assignment']=obj({'id':uuid,'patient_id':uuid,'facility_id':uuid,'staff_id':uuid,'assigned_by':uuid,'reason':string(),'valid_from':string(format='date-time'),'valid_until':string(format='date-time'),'revoked_at':string(format='date-time',nullable=True)},['id','patient_id','facility_id','staff_id','assigned_by','reason','valid_from','valid_until','revoked_at'])
schemas['BreakGlassInput']=obj({'reason':string(minLength=20,maxLength=1000),'duration_minutes':{'type':'integer','minimum':1,'maximum':240}},['reason','duration_minutes'])
schemas['BreakGlass']=obj({'id':uuid,'patient_id':uuid,'facility_id':uuid,'staff_id':uuid,'reason':string(),'granted_at':string(format='date-time'),'expires_at':string(format='date-time'),'reviewed_by':string(format='uuid',nullable=True),'reviewed_at':string(format='date-time',nullable=True),'review_outcome':string(nullable=True,enum=['appropriate','inappropriate',None]),'review_note':string(nullable=True)},['id','patient_id','facility_id','staff_id','reason','granted_at','expires_at','reviewed_by','reviewed_at','review_outcome','review_note'])
schemas['Approval']=obj({'id':uuid,'kind':string(enum=['admin_role_grant','mfa_reset']),'subject_id':uuid,'subject_version':version,'requested_by':uuid,'reason':string(),'expires_at':string(format='date-time'),'created_at':string(format='date-time'),'status':string(enum=['pending','approved','rejected','expired']),'reviewed_by':string(format='uuid',nullable=True),'reviewed_at':string(format='date-time',nullable=True),'review_note':string(nullable=True)},['id','kind','subject_id','subject_version','requested_by','reason','expires_at','created_at','status','reviewed_by','reviewed_at','review_note'])
schemas['PrivacyAlert']=obj({'id':uuid,'actor_id':uuid,'rule':string(enum=['patient_read_volume','mfa_denial_volume']),'window_start':string(format='date-time'),'window_end':string(format='date-time'),'event_count':{'type':'integer'}},['id','actor_id','rule','window_start','window_end','event_count'])
schemas['IdentifierInput']=obj({'kind':string(enum=['nida','insurance']),'issuer':string(minLength=1,maxLength=100),'value':string(minLength=1,maxLength=128,writeOnly=True)},['kind','issuer','value'])
metadata={'id':uuid,'patient_id':uuid,'kind':string(enum=['nida','insurance']),'issuer':string(),'created_at':string(format='date-time')}
schemas['IdentifierMetadata']=obj(metadata,list(metadata))
schemas['Identifier']=obj({**metadata,'value':string()},[*metadata,'value'])
idempotency=[{'name':'Idempotency-Key','in':'header','required':True,'schema':string(minLength=8,maxLength=128)}]
op('post','/api/v1/staff/patients/{id}/care-assignments','Assign care responsibility',ref('Assignment'),'AssignmentInput','care.manage',201,parameters=idempotency,description='Reception coordinator, same active facility, active clinical target, future expiry and attributable reason. Production grant creation requires enabled/approved care policy. Registry access remains demographic-only. Durable idempotency protects retries.')
op('post','/api/v1/staff/care-assignments/{id}/revoke','Revoke care responsibility',ref('Assignment'),permission='care.manage',description='Explicit audited revocation preserves history and immediately removes assignment-based access.')
op('post','/api/v1/staff/patients/{id}/break-glass','Request exceptional patient access',ref('BreakGlass'),'BreakGlassInput','break_glass.request',201,parameters=idempotency,description='Eligible doctor/nurse at the same active facility; default development policy capped at 240 minutes. Production requires the clinic approval reference. Different keys cannot create competing active grants. Expiry is enforced by PostgreSQL. Reason is retained in the restricted grant record referenced by audit, not ordinary logs.')
op('get','/api/v1/staff/privacy/break-glass','List exceptional access reviews',listing('BreakGlass',True),permission='break_glass.review',parameters=page,description='Includes unreviewed grants even after expiry; sensitive reasons require privileged privacy-review access.')
op('post','/api/v1/staff/privacy/break-glass/{id}/review','Review exceptional access',ref('BreakGlass'),obj({'outcome':string(enum=['appropriate','inappropriate']),'note':string(minLength=20,maxLength=1000)},['outcome','note']),'break_glass.review',description='Requester cannot self-review even after a role change. First review wins. Inappropriate review immediately removes the exceptional grant as care evidence.')
op('get','/api/v1/staff/privacy/alerts','List privacy alerts',listing('PrivacyAlert',True),permission='privacy.report',parameters=page,description='Configured fixed 15-minute read/MFA-denial windows; zero thresholds disable rules. Alerts deduplicate by actor/rule/window. Off-hours rules require a later approved schedule.')
op('get','/api/v1/staff/privacy/patients/{id}/access','Review patient access history',listing('AuditEvent'),permission='privacy.report',parameters=[{'name':'before','in':'query','schema':{'type':'integer','minimum':1}}],description='Privileged audited access to successful and denied events for a patient/resource identifier. Newest 100, exclusive before cursor. Does not return demographic/clinical bodies.')
op('post','/api/v1/staff/approvals','Request independent approval',ref('Approval'),obj({'kind':string(enum=['admin_role_grant','mfa_reset']),'subject_id':uuid,'reason':string(minLength=20,maxLength=1000)},['kind','subject_id','reason']),'approvals.request',201,parameters=idempotency,description='Requires a live MFA-verified administrator even in development. Captures subject version and expires after one hour. Direct creation/promotion of administrators is denied; bootstrap is owner-governed outside normal API.')
op('get','/api/v1/staff/approvals','List independent approvals',listing('Approval',True),permission='approvals.review',parameters=page,description='Requires a live MFA-verified administrator; expired timestamps remain visible even before a decision marks expired status.')
for decision in ['approve','reject']:
 op('post','/api/v1/staff/approvals/{id}/'+decision,decision.capitalize()+' independent request',ref('Approval'),obj({'note':string(minLength=20,maxLength=1000)},['note']),'approvals.review',description='Independent MFA-verified administrator, never requester. Current requester eligibility, expiry and subject version are checked under locks. Approval and its account change/session revocation commit together. Same terminal decision is replayable without repeating effects; contradictory/stale decisions return 409.')
metrics=op('get','/api/v1/staff/metrics','Scrape protected metrics',string(),permission='metrics.read',description='Static route templates/method/status counters and cumulative duration only; no patient/user/request IDs, names, tokens or query strings. Privileged MFA policy applies.')
metrics['responses']['200']={'description':'Prometheus text exposition','content':{'text/plain':{'schema':string()}}}
op('post','/api/v1/staff/patients/{id}/identifiers','Record encrypted patient identifier',ref('IdentifierMetadata'),'IdentifierInput','patients.write',201,parameters=idempotency,description='Field encryption with row/patient/kind/issuer binding and a separately keyed HMAC blind index. Creation replay metadata contains no plaintext identifier. Requires configured identifier keys, same scope and write permission; exact values never enter URLs/logs.')
op('get','/api/v1/staff/patients/{id}/identifiers','Read patient identifiers',listing('Identifier'),permission='patients.read',description='Authorized audited scoped read; decrypts up to 100 identifiers. Field authentication/key failures return 503. Clinical roles need care evidence; admin has no patient permission.')
op('post','/api/v1/staff/patient-identifiers/search','Search encrypted identifiers',obj({'patient_ids':array(uuid)},['patient_ids']),'IdentifierInput','patients.read',description='POST keeps sensitive lookup values out of URLs. Issuer is trimmed; value is trimmed/uppercased, with exact interior formatting. HMAC lookup returns up to 25 scoped patient IDs; every result and search is audited. No cross-facility suggestions are exposed.')
# Additional current session and login metadata.
schemas['Login']['properties']['device_label']=string(maxLength=80)
schemas['Session']['properties'].update({'last_seen_at':string(format='date-time'),'device_label':string(maxLength=80)})
schemas['Session']['required']+=['last_seen_at','device_label']
paths['/api/v1/auth/refresh']['post']['description']+=' Web sessions idle for fifteen minutes cannot refresh; mobile sessions retain the absolute seven-day lifetime.'
paths['/api/v1/staff/patients/{id}']['get']['description']+=' Clinical roles require an active care assignment or exceptional grant; denials are audited. PostgreSQL row-level policies repeat live permission/facility/care checks.'
paths['/api/v1/staff/patients']['get']['description']+=' Clinical lists contain only patients with active care evidence. Search hits are audited per patient.'
paths['/api/v1/staff/users']['post']['description']+=' New administrator roles require the independent approval workflow; this route creates ordinary staff only. Offline common-password screening applies.'
paths['/api/v1/staff/users/{id}']['put']['description']+=' Promoting an ordinary account to administrator requires independent approval.'
spec={'openapi':'3.0.3','info':{'title':'Spartial Polyclinic Foundation API','version':'0.3.0','description':'Milestone A implementation. All listed routes exist; later clinical/patient-access modules are tracked in docs/MODULE_STATUS.md. Not clinic accepted. Timestamps RFC3339 UTC, date-only YYYY-MM-DD. Future financial amounts must be exact decimal strings; no financial endpoints are implemented.'},'servers':[{'url':'http://localhost:8080','description':'Local development'}],'paths':paths,'components':{'securitySchemes':{'bearerAuth':{'type':'http','scheme':'bearer','bearerFormat':'opaque','description':'Random 256-bit opaque access credential; hashed server-side, session and live account/permissions checked on each protected request. No JWT algorithm or client-supplied claims.'}},'schemas':schemas},'security':[{'bearerAuth':[]}]}
Path('api/openapi/openapi.json').write_text(json.dumps(spec,indent=2)+'\n')
print(f'Generated {sum(len(v) for v in paths.values())} operations.')
